const rows = $input.all().map((item) => item.json);
if (!rows.length) return [];
const groups = new Map();
for (const row of rows) {
  const key = String(row.campaign_id) + '::' + String(row.doctor_id);
  if (!groups.has(key)) groups.set(key, []);
  groups.get(key).push(row);
}
const invitations = [];
for (const group of groups.values()) {
  if (group.length !== 3) throw new Error('Expected exactly three topic links for each doctor.');
  group.sort((a, b) => Number(a.topic_sort_order) - Number(b.topic_sort_order));
  const first = group[0];
  const previewOnly = first.preview_only === true || String(first.preview_only).toLowerCase() === 'true';
  const lines = [
    'Hello ' + first.doctor_name + ',',
    '',
    previewOnly ? 'You are invited to preview Apex Dental Partners\' AI content interview experience.' : 'We have three article topics for you to choose from.',
    '',
    previewOnly ? 'Choose whichever topic you would most like to discuss, then use its secure link to try a short voice interview:' : 'Pick the topic you would most like to discuss, then use its secure link to start a voice interview:',
    ''
  ];
  for (const row of group) lines.push(row.topic_sort_order + '. ' + row.topic_title, row.interview_url, '');
  lines.push('Before you begin, choose a quiet place. Background conversations and other noise can interrupt the voice interviewer. Headphones with a microphone may help.', '');
  if (previewOnly) lines.push('This presentation preview saves your interview transcript for evaluation, but it will not create, review, or publish an article.', '');
  lines.push('These links expire in 30 days. Please do not include patient-identifying information in the interview.', '', 'Apex Dental Partners');
  invitations.push({ json: {
    doctor_id: first.doctor_id,
    article_id: '',
    campaign_id: first.campaign_id,
    communication_type: 'CAMPAIGN_INVITATION',
    subject: previewOnly ? 'Try Apex\'s AI content interview: ' + first.campaign_name : 'Choose your article topic: ' + first.campaign_name,
    message_text: lines.join(String.fromCharCode(10)),
    action_url: ''
  }});
}
return invitations;

const delivered = $json.status === 'SENT' || $json.success === true;
return { json: {
  campaign_id: String($json.campaign_id || ''),
  doctor_id: String($json.doctor_id || ''),
  delivered,
  status: String($json.status || (delivered ? 'SENT' : 'FAILED')),
  error: $json.error ? String($json.error) : ''
} };

