UPDATE `apex-marketing-n8n.automated_article_creation.campaign_doctors`
SET status = 'INVITED', invited_at = CURRENT_TIMESTAMP(), updated_at = CURRENT_TIMESTAMP()
WHERE campaign_id = @campaign_id AND doctor_id = @doctor_id AND status IN ('READY', 'SENDING');
INSERT INTO `apex-marketing-n8n.automated_article_creation.workflow_events`
(event_id, entity_type, entity_id, event_type, event_timestamp, source_system, workflow_execution_id, payload)
VALUES (GENERATE_UUID(), 'campaign_doctor', CONCAT(@campaign_id, ':', @doctor_id), 'interview.invitation_sent', CURRENT_TIMESTAMP(), 'n8n', NULL, TO_JSON(STRUCT(@campaign_id AS campaign_id, @doctor_id AS doctor_id)));
SELECT @campaign_id AS campaign_id, @doctor_id AS doctor_id, 'INVITED' AS status;

DECLARE v_failure_count INT64 DEFAULT (
  SELECT COUNT(*)
  FROM `apex-marketing-n8n.automated_article_creation.communications`
  WHERE campaign_id = @campaign_id
    AND doctor_id = @doctor_id
    AND communication_type = 'CAMPAIGN_INVITATION'
    AND status = 'FAILED'
);
DECLARE v_next_status STRING DEFAULT IF(v_failure_count >= 2, 'COMMUNICATION_FAILED', 'READY');

UPDATE `apex-marketing-n8n.automated_article_creation.campaign_doctors`
SET status = v_next_status, updated_at = CURRENT_TIMESTAMP()
WHERE campaign_id = @campaign_id AND doctor_id = @doctor_id AND status = 'SENDING';

INSERT INTO `apex-marketing-n8n.automated_article_creation.workflow_events`
(event_id, entity_type, entity_id, event_type, event_timestamp, source_system, workflow_execution_id, payload)
VALUES (
  GENERATE_UUID(),
  'campaign_doctor',
  CONCAT(@campaign_id, ':', @doctor_id),
  IF(v_next_status = 'READY', 'interview.invitation_retry_queued', 'communication.failed'),
  CURRENT_TIMESTAMP(),
  'n8n:campaign-invitation',
  NULL,
  TO_JSON(STRUCT(
    @campaign_id AS campaign_id,
    @doctor_id AS doctor_id,
    v_failure_count AS failure_count,
    v_next_status AS next_status,
    NULLIF(@error, '') AS error
  ))
);

SELECT @campaign_id AS campaign_id, @doctor_id AS doctor_id, v_next_status AS status;
